/**
 * Returns the hotspot label in the student's target language.
 * Falls back to the original hotspot.label if no translation is found.
 */
export function getHotspotLabel(hotspotId: string, hotspotLabel: string, targetLang: string): string {
  const translations = HOTSPOT_TRANSLATIONS[hotspotId];
  if (!translations) return hotspotLabel;
  // targetLang can be "fr-FR", "en-US", "de-DE" etc — extract base code
  const baseLang = targetLang.split("-")[0].toLowerCase();
  return translations[baseLang] || translations["en"] || hotspotLabel;
}
